## Hangman Extended

### Word Categories

```xiom
type WordBank {
  category: Str;
  words: Vec[Str];
}

fn create_word_bank(category: Int) -> WordBank {
  let mut bank = WordBank{ category: "Animals", words: Vec[Str].new() };
  if category == 0 {
    bank.words.push("ELEPHANT");
    bank.words.push("GIRAFFE");
    bank.words.push("PENGUIN");
  } else if category == 1 {
    bank.words.push("PYTHON");
    bank.words.push("JAVASCRIPT");
    bank.words.push("ASSEMBLY");
  };
  bank
}
```

