### ASCII Hangman

```xiom
fn draw_hangman(lives: Int) -> Str {
  if lives == 6 { return "+---+\n    |\n    |\n    |\n   ==="; };
  if lives == 5 { return "+---+\nO   |\n    |\n    |\n   ==="; };
  if lives == 4 { return "+---+\nO   |\n|   |\n    |\n   ==="; };
  if lives == 3 { return "+---+\nO   |\n/|  |\n    |\n   ==="; };
  if lives == 2 { return "+---+\nO   |\n/|\\ |\n    |\n   ==="; };
  if lives == 1 { return "+---+\nO   |\n/|\\ |\n/   |\n   ==="; };
  "+---+\nO   |\n/|\\ |\n/ \\ |\n   ===";
}
```

### Scoring

```xiom
fn calculate_round_score(word: Str, lives_remaining: Int) -> Int {
  word.len() * lives_remaining * 10
}
```

### Multi-Round Flow

```xiom
fn play_game_session(rounds: Int) {
  let mut session = GameSession{ total_score: 0, rounds_played: 0, rounds_won: 0, current_round: 1, lives_per_round: 7 };

  while session.current_round <= rounds {
    let bank = create_word_bank(session.current_round % 2);
    let word = pick_word(&bank);
    let won = play_round(word, session.lives_per_round);
    session.rounds_played += 1;
    if won { session.rounds_won += 1; };
    session.current_round += 1;
  };

  io.println(session.total_score);
  io.println(session.rounds_won);
}
```

