use xiom.io;

use xiom.string;
type HangmanSession = {
  score: Int;
  rounds_won: Int;
  rounds_lost: Int;
}

fn play_round(word: Str, max_lives: Int) -> Bool {
  var display = "";
  var i = 0;
  while i < word.len() { display = string.str_concat(display, "_"); i += 1; };

  var lives = max_lives;
  var found = 0;

  let guesses: Vec[Char] = Vec[Char].new();
  guesses.push('E'); guesses.push('A'); guesses.push('I');
  guesses.push('O'); guesses.push('U'); guesses.push('T');
  guesses.push('N'); guesses.push('S'); guesses.push('R');

  var gi = 0;
  while lives > 0 && found < word.len() && gi < guesses.len() {
    let g = guesses.get(gi).unwrap();
    var hit = false;
    var j = 0;
    while j < word.len() {
      if word.char_at(j) == g {
        found += 1;
        hit = true;
      };
      j += 1;
    };
    if !hit { lives -= 1; };
    gi += 1;
  };
  found == word.len()
}

fn main() -> Int {
  var session = HangmanSession{ score: 0, rounds_won: 0, rounds_lost: 0 };
  if play_round("PYTHON", 6) { session.rounds_won += 1; } else { session.rounds_lost += 1; };
  if play_round("JAVA", 6) { session.rounds_won += 1; } else { session.rounds_lost += 1; };
  io.println(session.rounds_won.to_str());
  io.println(session.rounds_lost.to_str());
  return 0;
}
